-- Oxygen11 production MySQL persistence
CREATE TABLE IF NOT EXISTS oxygen_sessions (token_hash CHAR(64) PRIMARY KEY,uid VARCHAR(191) NOT NULL,role VARCHAR(32) NOT NULL,created_at BIGINT NOT NULL,expires_at BIGINT NOT NULL,INDEX idx_sessions_expires(expires_at),INDEX idx_sessions_uid(uid)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS oxygen_orders (order_id BIGINT PRIMARY KEY,client_uid VARCHAR(191) NOT NULL,client_name VARCHAR(150) NOT NULL,phone VARCHAR(40) NOT NULL,service_category VARCHAR(100) NOT NULL,priority VARCHAR(20) NOT NULL,location TEXT NOT NULL,notes TEXT,status VARCHAR(40) NOT NULL,dispatch_type VARCHAR(20) NOT NULL,provider_uid VARCHAR(191),provider_name VARCHAR(150),labor DECIMAL(12,2) NOT NULL DEFAULT 0,parts DECIMAL(12,2) NOT NULL DEFAULT 0,discount DECIMAL(12,2) NOT NULL DEFAULT 0,total DECIMAL(12,2) NOT NULL DEFAULT 0,commission DECIMAL(12,2) NOT NULL DEFAULT 0,provider_net DECIMAL(12,2) NOT NULL DEFAULT 0,payment_method VARCHAR(40),payment_status VARCHAR(30) NOT NULL DEFAULT 'pending',payment_reference VARCHAR(191),invoice_id VARCHAR(191),invoice_status VARCHAR(30),invoice_issued_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX idx_orders_client(client_uid),INDEX idx_orders_provider(provider_uid),INDEX idx_orders_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS oxygen_order_audit (id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL,action VARCHAR(191) NOT NULL,actor VARCHAR(191) NOT NULL,created_at DATETIME NOT NULL,INDEX idx_audit_order(order_id),CONSTRAINT fk_oxygen_audit_order FOREIGN KEY(order_id) REFERENCES oxygen_orders(order_id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS oxygen_providers (uid VARCHAR(191) PRIMARY KEY,full_name VARCHAR(150) NOT NULL,phone VARCHAR(40),service_types VARCHAR(500) NOT NULL DEFAULT '',status VARCHAR(30) NOT NULL DEFAULT 'active',available TINYINT(1) NOT NULL DEFAULT 1,latitude DECIMAL(10,8),longitude DECIMAL(11,8),last_assigned_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX idx_provider_status(status),INDEX idx_provider_available(available)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS oxygen_payments (payment_id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL,client_uid VARCHAR(191) NOT NULL,amount DECIMAL(12,2) NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'SAR',method VARCHAR(40) NOT NULL,provider VARCHAR(40) NOT NULL,status VARCHAR(30) NOT NULL,external_reference VARCHAR(191),idempotency_key VARCHAR(191) NOT NULL,provider_metadata JSON NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,paid_at DATETIME NULL,UNIQUE KEY uq_payment_idempotency(idempotency_key),INDEX idx_payment_order(order_id),INDEX idx_payment_client(client_uid),CONSTRAINT fk_oxygen_payment_order FOREIGN KEY(order_id) REFERENCES oxygen_orders(order_id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
